cd /tmp/neutrino-fast-live-LY3jZs/parallel_analysis/standard/0 && node <<'EOF'
const fs = require('fs'), path = require('path');
const dir = process.cwd();
const REGIONS = ['north','south','east','west'];
const EXPECTED = { north:{count:10,units:90,weighted:167}, south:{count:10,units:94,weighted:171}, east:{count:10,units:98,weighted:209}, west:{count:10,units:85,weighted:145} };
const fail = (m) => { console.error('FAIL: ' + m); process.exit(1); };
const okInt = (v) => Number.isInteger(v);

// 1. answer.json parses in full and has exactly the required schema
const raw = fs.readFileSync(path.join(dir,'answer.json'),'utf8');
let ans;
try { ans = JSON.parse(raw); } catch (e) { fail('answer.json is not valid JSON: ' + e.message); }
if (typeof ans !== 'object' || ans === null || Array.isArray(ans)) fail('answer.json root is not an object');
const topKeys = Object.keys(ans).sort();
if (topKeys.join(',') !== 'grand_units,grand_weighted,regions') fail('unexpected top-level keys: ' + topKeys.join(','));
if (typeof ans.regions !== 'object' || ans.regions === null || Array.isArray(ans.regions)) fail('regions is not an object');
const regionKeys = Object.keys(ans.regions).sort();
if (regionKeys.join(',') !== REGIONS.slice().sort().join(',')) fail('regions keys are ' + regionKeys.join(',') + ', expected north,south,east,west');
for (const r of REGIONS) {
  const e = ans.regions[r];
  const k = Object.keys(e || {}).sort();
  if (k.join(',') !== 'count,units,weighted') fail(`${r}: entry keys are ${k.join(',')}`);
  for (const f of ['count','units','weighted']) if (!okInt(e[f])) fail(`${r}.${f} is not an integer: ${JSON.stringify(e[f])}`);
}
if (!okInt(ans.grand_units) || !okInt(ans.grand_weighted)) fail('grand totals are not integers');

// 2. recompute every region from its own source file and compare
const rec = {};
let sumUnits = 0, sumWeighted = 0, sumCount = 0;
for (const r of REGIONS) {
  const f = path.join(dir, r + '.json');
  const src = fs.readFileSync(f, 'utf8');
  let data;
  try { data = JSON.parse(src); } catch (e) { fail(`${r}.json is not valid JSON: ${e.message}`); }
  if (!Array.isArray(data)) fail(`${r}.json top-level is not an array`);
  let u = 0, w = 0;
  data.forEach((row, i) => {
    if (typeof row !== 'object' || row === null) fail(`${r}[${i}] is not an object`);
    if (!okInt(row.units) || !okInt(row.weight)) fail(`${r}[${i}] units/weight not integers`);
    u += row.units; w += row.units * row.weight;
  });
  const computed = { count: data.length, units: u, weighted: w };
  const written = ans.regions[r];
  if (computed.count !== written.count || computed.units !== written.units || computed.weighted !== written.weighted)
    fail(`${r}: answer.json ${JSON.stringify(written)} != source ${JSON.stringify(computed)}`);
  if (EXPECTED[r].count !== computed.count || EXPECTED[r].units !== computed.units || EXPECTED[r].weighted !== computed.weighted)
    fail(`${r}: source diverged from verified step-6 baseline ${JSON.stringify(EXPECTED[r])}`);
  rec[r] = computed; sumCount += computed.count; sumUnits += computed.units; sumWeighted += computed.weighted;
  console.log(`${r.padEnd(5)} count=${computed.count} units=${computed.units} weighted=${computed.weighted} | answer.json MATCH | full-file parse OK`);
}

// 3. grand totals must equal the sums of the per-region values
const uSum = REGIONS.reduce((a,r) => a + ans.regions[r].units, 0);
const wSum = REGIONS.reduce((a,r) => a + ans.regions[r].weighted, 0);
if (ans.grand_units !== uSum) fail(`grand_units ${ans.grand_units} != sum of regions ${uSum}`);
if (ans.grand_weighted !== wSum) fail(`grand_weighted ${ans.grand_weighted} != sum of regions ${wSum}`);
if (ans.grand_units !== sumUnits || ans.grand_weighted !== sumWeighted) fail('grand totals != recomputed source totals');
if (ans.grand_units !== 367 || ans.grand_weighted !== 692) fail('grand totals != verified baseline 367/692');

// 4. source completeness + no unrelated inputs in the fixture
const present = fs.readdirSync(dir).sort();
const allowed = ['answer.json','east.json','north.json','south.json','west.json'];
if (present.join(',') !== allowed.join(',')) fail('unexpected fixture contents: ' + present.join(','));
for (const r of REGIONS) if (!present.includes(r + '.json')) fail('missing source ' + r + '.json');
const missing = REGIONS.filter(r => !(r in rec));
if (missing.length) fail('regions missing from verification: ' + missing.join(','));

console.log('---');
console.log(`schema OK: regions{north,south,east,west}{count,units,weighted} + grand_units + grand_weighted`);
console.log(`fixture contents: ${present.join(', ')} (no framework, no unrelated inputs)`);
console.log(`totals: count=${sumCount} grand_units=${ans.grand_units} grand_weighted=${ans.grand_weighted}`);
console.log('PASS: answer.json verified against all four original sources');
EOF
